175	    public static class ShadowDrawable extends DrawableWrapper {
176	        // used to calculate content padding
177	        private static final double COS_45 = Math.cos(Math.toRadians(45));
178	
179	        private float mShadowMultiplier = 1f;
180	
181	        private float mShadowTopScale    = 1f;
182	        private float mShadowHorizScale  = 1f;
183	        private float mShadowBottomScale = 1f;
184	
185	        private Paint mCornerShadowPaint;
186	        private Paint mEdgeShadowPaint;
187	
188	        private RectF mContentBounds;
189	
190	        private float mCornerRadius;
191	
192	        private Path mCornerShadowPath;
193	
194	        // updated value with inset
195	        private float mMaxShadowSize;
196	        // actual value set by developer
197	        private float mRawMaxShadowSize;
198	
199	        // multiplied value to account for shadow offset
200	        private float mShadowSize;
201	        // actual value set by developer
202	        private float mRawShadowSize;
203	
204	        private boolean mDirty = true;
205	
206	        private final int mShadowStartColor;
207	        private final int mShadowEndColor;
208	
209	        private boolean mAddPaddingForCorners = false;
210	
211	        private float mRotation;
212	
213	        private boolean isCircle;
214	
215	        public ShadowDrawable(Drawable content, float radius,
216	                              float shadowSize, float maxShadowSize, int shadowColor, boolean isCircle) {
217	            super(content);
218	            mShadowStartColor = shadowColor;
219	            mShadowEndColor = mShadowStartColor & 0x00ffffff;
220	            this.isCircle = isCircle;
221	            if (isCircle) {
222	                mShadowMultiplier = 1;
223	                mShadowTopScale = 1;
224	                mShadowHorizScale = 1;
225	                mShadowBottomScale = 1;
226	            }
227	
228	            mCornerShadowPaint = new Paint(Paint.ANTI_ALIAS_FLAG | Paint.DITHER_FLAG);
229	            mCornerShadowPaint.setStyle(Paint.Style.FILL);
230	            mCornerRadius = Math.round(radius);
231	            mContentBounds = new RectF();
232	            mEdgeShadowPaint = new Paint(mCornerShadowPaint);
233	            mEdgeShadowPaint.setAntiAlias(false);
234	            setShadowSize(shadowSize, maxShadowSize);
235	        }
