237	        /**
238	         * Casts the value to an even integer.
239	         */
240	        private static int toEven(float value) {
241	            int i = Math.round(value);
242	            return (i % 2 == 1) ? i - 1 : i;
243	        }
244	
245	        public void setAddPaddingForCorners(boolean addPaddingForCorners) {
246	            mAddPaddingForCorners = addPaddingForCorners;
247	            invalidateSelf();
248	        }
249	
250	        @Override
251	        public void setAlpha(int alpha) {
252	            super.setAlpha(alpha);
253	            mCornerShadowPaint.setAlpha(alpha);
254	            mEdgeShadowPaint.setAlpha(alpha);
255	        }
