257	        @Override
258	        protected void onBoundsChange(Rect bounds) {
259	            mDirty = true;
260	        }
261	
262	        void setShadowSize(float shadowSize, float maxShadowSize) {
263	            if (shadowSize < 0 || maxShadowSize < 0) {
264	                throw new IllegalArgumentException("invalid shadow size");
265	            }
266	            shadowSize = toEven(shadowSize);
267	            maxShadowSize = toEven(maxShadowSize);
268	            if (shadowSize > maxShadowSize) {
269	                shadowSize = maxShadowSize;
270	            }
271	            if (mRawShadowSize == shadowSize && mRawMaxShadowSize == maxShadowSize) {
272	                return;
273	            }
274	            mRawShadowSize = shadowSize;
275	            mRawMaxShadowSize = maxShadowSize;
276	            mShadowSize = Math.round(shadowSize * mShadowMultiplier);
277	            mMaxShadowSize = maxShadowSize;
278	            mDirty = true;
279	            invalidateSelf();
280	        }
