282	        @Override
283	        public boolean getPadding(Rect padding) {
284	            int vOffset = (int) Math.ceil(calculateVerticalPadding(mRawMaxShadowSize, mCornerRadius,
285	                    mAddPaddingForCorners));
286	            int hOffset = (int) Math.ceil(calculateHorizontalPadding(mRawMaxShadowSize, mCornerRadius,
287	                    mAddPaddingForCorners));
288	            padding.set(hOffset, vOffset, hOffset, vOffset);
289	            return true;
290	        }
