292	        private float calculateVerticalPadding(float maxShadowSize, float cornerRadius,
293	                                               boolean addPaddingForCorners) {
294	            if (addPaddingForCorners) {
295	                return (float) (maxShadowSize * mShadowMultiplier + (1 - COS_45) * cornerRadius);
296	            } else {
297	                return maxShadowSize * mShadowMultiplier;
298	            }
299	        }
