301	        private static float calculateHorizontalPadding(float maxShadowSize, float cornerRadius,
302	                                                        boolean addPaddingForCorners) {
303	            if (addPaddingForCorners) {
304	                return (float) (maxShadowSize + (1 - COS_45) * cornerRadius);
305	            } else {
306	                return maxShadowSize;
307	            }
308	        }
