343	        private void drawShadow(Canvas canvas) {
344	            if (isCircle) {
345	                int saved = canvas.save();
346	                canvas.translate(mContentBounds.centerX(), mContentBounds.centerY());
347	                canvas.drawPath(mCornerShadowPath, mCornerShadowPaint);
348	                canvas.restoreToCount(saved);
349	                return;
350	            }
351	
352	            final int rotateSaved = canvas.save();
353	            canvas.rotate(mRotation, mContentBounds.centerX(), mContentBounds.centerY());
354	
355	            final float edgeShadowTop = -mCornerRadius - mShadowSize;
356	            final float shadowOffset = mCornerRadius;
357	            final boolean drawHorizontalEdges = mContentBounds.width() - 2 * shadowOffset > 0;
358	            final boolean drawVerticalEdges = mContentBounds.height() - 2 * shadowOffset > 0;
359	
360	            final float shadowOffsetTop = mRawShadowSize - (mRawShadowSize * mShadowTopScale);
361	            final float shadowOffsetHorizontal = mRawShadowSize - (mRawShadowSize * mShadowHorizScale);
362	            final float shadowOffsetBottom = mRawShadowSize - (mRawShadowSize * mShadowBottomScale);
363	
364	            final float shadowScaleHorizontal = shadowOffset == 0 ? 1 : shadowOffset / (shadowOffset + shadowOffsetHorizontal);
365	            final float shadowScaleTop = shadowOffset == 0 ? 1 : shadowOffset / (shadowOffset + shadowOffsetTop);
366	            final float shadowScaleBottom = shadowOffset == 0 ? 1 : shadowOffset / (shadowOffset + shadowOffsetBottom);
367	
368	            // LT
369	            int saved = canvas.save();
370	            canvas.translate(mContentBounds.left + shadowOffset, mContentBounds.top + shadowOffset);
371	            canvas.scale(shadowScaleHorizontal, shadowScaleTop);
372	            canvas.drawPath(mCornerShadowPath, mCornerShadowPaint);
373	            if (drawHorizontalEdges) {
374	                // TE
375	                canvas.scale(1f / shadowScaleHorizontal, 1f);
376	                canvas.drawRect(0, edgeShadowTop,
377	                        mContentBounds.width() - 2 * shadowOffset, -mCornerRadius,
378	                        mEdgeShadowPaint);
379	            }
380	            canvas.restoreToCount(saved);
381	            // RB
382	            saved = canvas.save();
383	            canvas.translate(mContentBounds.right - shadowOffset, mContentBounds.bottom - shadowOffset);
384	            canvas.scale(shadowScaleHorizontal, shadowScaleBottom);
385	            canvas.rotate(180f);
386	            canvas.drawPath(mCornerShadowPath, mCornerShadowPaint);
387	            if (drawHorizontalEdges) {
388	                // BE
389	                canvas.scale(1f / shadowScaleHorizontal, 1f);
390	                canvas.drawRect(0, edgeShadowTop,
391	                        mContentBounds.width() - 2 * shadowOffset, -mCornerRadius,
392	                        mEdgeShadowPaint);
393	            }
394	            canvas.restoreToCount(saved);
395	            // LB
396	            saved = canvas.save();
397	            canvas.translate(mContentBounds.left + shadowOffset, mContentBounds.bottom - shadowOffset);
398	            canvas.scale(shadowScaleHorizontal, shadowScaleBottom);
399	            canvas.rotate(270f);
400	            canvas.drawPath(mCornerShadowPath, mCornerShadowPaint);
401	            if (drawVerticalEdges) {
402	                // LE
403	                canvas.scale(1f / shadowScaleBottom, 1f);
404	                canvas.drawRect(0, edgeShadowTop,
405	                        mContentBounds.height() - 2 * shadowOffset, -mCornerRadius, mEdgeShadowPaint);
406	            }
407	            canvas.restoreToCount(saved);
408	            // RT
409	            saved = canvas.save();
410	            canvas.translate(mContentBounds.right - shadowOffset, mContentBounds.top + shadowOffset);
411	            canvas.scale(shadowScaleHorizontal, shadowScaleTop);
412	            canvas.rotate(90f);
413	            canvas.drawPath(mCornerShadowPath, mCornerShadowPaint);
414	            if (drawVerticalEdges) {
415	                // RE
416	                canvas.scale(1f / shadowScaleTop, 1f);
417	                canvas.drawRect(0, edgeShadowTop,
418	                        mContentBounds.height() - 2 * shadowOffset, -mCornerRadius, mEdgeShadowPaint);
419	            }
420	            canvas.restoreToCount(saved);
421	
422	            canvas.restoreToCount(rotateSaved);
423	        }
