425	        private void buildShadowCorners() {
426	            if (isCircle) {
427	                float size = mContentBounds.width() / 2 - 1f;
428	                RectF innerBounds = new RectF(-size, -size, size, size);
429	                RectF outerBounds = new RectF(innerBounds);
430	                outerBounds.inset(-mShadowSize, -mShadowSize);
431	
432	                if (mCornerShadowPath == null) {
433	                    mCornerShadowPath = new Path();
434	                } else {
435	                    mCornerShadowPath.reset();
436	                }
437	                mCornerShadowPath.setFillType(Path.FillType.EVEN_ODD);
438	                mCornerShadowPath.moveTo(-size, 0);
439	                mCornerShadowPath.rLineTo(-mShadowSize, 0);
440	                // outer arc
441	                mCornerShadowPath.arcTo(outerBounds, 180f, 180f, false);
442	                mCornerShadowPath.arcTo(outerBounds, 0f, 180f, false);
443	                // inner arc
444	                mCornerShadowPath.arcTo(innerBounds, 180f, 180f, false);
445	                mCornerShadowPath.arcTo(innerBounds, 0f, 180f, false);
446	                mCornerShadowPath.close();
447	
448	                float shadowRadius = -outerBounds.top;
449	                if (shadowRadius > 0f) {
450	                    float startRatio = size / shadowRadius;
451	                    mCornerShadowPaint.setShader(new RadialGradient(0, 0, shadowRadius,
452	                            new int[]{0, mShadowStartColor, mShadowEndColor}, new float[]{0.0F, startRatio, 1.0F},
453	                            Shader.TileMode.CLAMP));
454	                }
455	                return;
456	            }
457	
458	            RectF innerBounds = new RectF(-mCornerRadius, -mCornerRadius, mCornerRadius, mCornerRadius);
459	            RectF outerBounds = new RectF(innerBounds);
460	            outerBounds.inset(-mShadowSize, -mShadowSize);
461	
462	            if (mCornerShadowPath == null) {
463	                mCornerShadowPath = new Path();
464	            } else {
465	                mCornerShadowPath.reset();
466	            }
467	            mCornerShadowPath.setFillType(Path.FillType.EVEN_ODD);
468	            mCornerShadowPath.moveTo(-mCornerRadius, 0);
469	            mCornerShadowPath.rLineTo(-mShadowSize, 0);
470	            // outer arc
471	            mCornerShadowPath.arcTo(outerBounds, 180f, 90f, false);
472	            // inner arc
473	            mCornerShadowPath.arcTo(innerBounds, 270f, -90f, false);
474	            mCornerShadowPath.close();
475	
476	            float shadowRadius = -outerBounds.top;
477	            if (shadowRadius > 0f) {
478	                float startRatio = mCornerRadius / shadowRadius;
479	                mCornerShadowPaint.setShader(new RadialGradient(0, 0, shadowRadius,
480	                        new int[]{0, mShadowStartColor, mShadowEndColor}, new float[]{0F, startRatio, 1F},
481	                        Shader.TileMode.CLAMP));
482	            }
483	
484	            // we offset the content shadowSize/2 pixels up to make it more realistic.
485	            // this is why edge shadow shader has some extra space
486	            // When drawing bottom edge shadow, we use that extra space.
487	            mEdgeShadowPaint.setShader(new LinearGradient(0, innerBounds.top, 0, outerBounds.top,
488	                    mShadowStartColor, mShadowEndColor, Shader.TileMode.CLAMP));
489	            mEdgeShadowPaint.setAntiAlias(false);
490	        }
491	
492	        private void buildComponents(Rect bounds) {
493	            // Card is offset mShadowMultiplier * maxShadowSize to account for the shadow shift.
494	            // We could have different top-bottom offsets to avoid extra gap above but in that case
495	            // center aligning Views inside the CardView would be problematic.
496	            if (isCircle) {
497	                mCornerRadius = bounds.width() / 2;
498	            }
499	            final float verticalOffset = mRawMaxShadowSize * mShadowMultiplier;
500	            mContentBounds.set(bounds.left + mRawMaxShadowSize, bounds.top + verticalOffset,
501	                    bounds.right - mRawMaxShadowSize, bounds.bottom - verticalOffset);
502	
503	            getWrappedDrawable().setBounds((int) mContentBounds.left, (int) mContentBounds.top,
504	                    (int) mContentBounds.right, (int) mContentBounds.bottom);
505	            buildShadowCorners();
506	        }
