public static <T> void reverse(T[] array) {
    if (array == null) {
        return;
    }
    int i = 0;
    int j = array.length - 1;
    T tmp;
    while (j > i) {
        tmp = array[j];
        array[j] = array[i];
        array[i] = tmp;
        j--;
        i++;
    }
}

